    "description": [
      "One of 210 LaFerrari Apertas ever built and specially commissioned by former Ferrari Chairman &amp; CEO Sergio Marchionne for a highly influential person in Motorsport.",
      "Believed to be the last example produced, it was delivered new with an extensive specification that includes a carbon fibre removable hardtop, carbon fibre rear fog lamp, carbon fibre wheel caps, carbon fibre exterior mirrors, visible carbon fibre lower exterior sections, matt black sports exhaust pipes, 20-inch matt black forged wheels, Rosso Corsa brake calipers and a front suspension lifter. The Nero leather and Alcantara interior features Rosso details, prancing horses embroidered onto the headrests in Nero, large seat cushions, an integrated audio system with navigation and a Navtrak anti-theft system.",
      "With fewer than 1,000 miles covered from new, this example represents a rare opportunity to acquire one of these special cars and benefits from exceptional provenance and maintenance history, as further detailed below.",
      "July 2019 at 52 miles — Annual service at H.R. Owen",
      "April 2021 at 53 miles — Annual service at H.R. Owen",
      "August 2022 at 443 miles — Annual service at Dick Lovett Swindon",
      "August 2023 at 917 miles — Annual service at Dick Lovett Swindon",
      "July 2024 at 937 miles — Annual service at Graypaul Nottingham",
      "July 2025 at 982 miles — Annual service at Ferrari Sydney",
      "Offered complete with its original books, including the service/warranty supplement and the sought-after Ferrari “Yellow Book”, spare key, Ferrari battery charger, Ferrari car cover and a well-documented history file."
    ],
    "specs": {
      "mileage": "987 Miles",
      "body_style": "Targa",
      "transmission": "Semi-automatic",
      "engine_capacity": "6262cc",
      "fuel": "Hybrid"
    }
