    "description": [
      "The Porsche 964 Turbo represents one of the most iconic evolutions of the 911, combining classic air-cooled character with meaningful advancements in performance and usability. Retaining the raw, analogue feel of earlier Turbos, it delivers a truly engaging driving experience defined by its unmistakable surge of boost and driver-focused nature.",
      "Powered by the renowned turbocharged flat-six, the 964 Turbo evolved from the 3.3-litre unit of the 930 to the highly sought-after 3.6-litre variant, now regarded as one of the most collectable air-cooled 911s. Of particular significance is the rare X88 engine upgrade, a factory power kit developed and installed by Porsche’s Exclusive Department. This highly desirable upgrade enhances performance through a series of uprated components, including revised turbochargers, modified camshafts, reworked cylinder heads and improved cooling systems. Power is increased from the standard 360 bhp to 385 bhp, further elevating the already formidable performance and adding to its notable exclusivity and collectability.",
      "The car also benefits from a great specification and a host of optional extras which include; a sunroof, air conditioning, electrically adjustable left and right comfort seats, soft-look leather seats front and rear, split rear seat backrest, top-tinted windscreen, 18-inch split-rim polished alloys, power steering, headlight washer system, cassette radio, additional amplifier and rear wiper.",
      "Presented in exceptional condition throughout and fresh from a major service by a marque specialist. The car is offered with its original books, including the all-important guarantee/maintenance supplements, leather pouch, spare key, tool roll, spare wheel, car cover, battery conditioner and a dedicated history file that includes its Porsche Certificate of Authenticity."
    ],
