    "description": [
      "Few cars capture the essence of 1980s performance quite like the Porsche 930 Turbo. Introduced in the mid-1970s as Porsche&#8217;s first production turbocharged 911, the 930 evolved into an icon of both engineering ambition and raw driving character. By 1988, it represented the most refined iteration of the original Turbo formula before the arrival of the 964 generation, blending unmistakable styling with formidable performance.",
      "At its heart lies a 3.3-litre turbocharged flat-six, delivering a dramatic surge of power that defined the 930&#8217;s reputation. Paired with a robust four-speed manual gearbox, it offers a level of interaction, feel and communication that modern performance cars rarely achieve. The combination of rear-engine balance and turbocharged boost creates a uniquely engaging character, one that has cemented the 930 as one of the most thrilling and talked-about 911 variants ever produced.",
      "Visually, the 930 Turbo is instantly recognisable. Its wide rear arches, pronounced &#8216;whale tail&#8217; spoiler and purposeful stance give it an unmistakable road presence, while subtle detailing reflects Porsche&#8217;s relentless focus on function-led design.",
      "This superb UK-supplied example benefits from single ownership for the last 32 years and has been maintained to a high standard throughout its life. Original factory specification includes driver and passenger sports seats with electric height adjustment, heated driver and passenger seats, sunroof, rear seat belts, luggage compartment trimmed in black velour carpet, recoil bumpers, Blaupunkt Toronto radio cassette and amplifier system.",
      "Having just undergone a comprehensive service by a model experts Autofarm (1973) Ltd, the car is offered in superb condition throughout and is accompanied by an exceptionally well-documented history file. Included is the original new vehicle sales invoice dated March 1994, followed by a substantial collection of service invoices dating from July 1994 to the present day. The history file is further supported by MOT certificates from August 1991 onwards and a collection of tax discs dating from July 1996 onwards. Also accompanying the car is its original Porsche handbook wallet, complete with the original maintenance record book, an item very rarely found with these cars today, along with the driver&#8217;s manual, Porsche Service Stations booklet, Porsche Ownership Pocket Guide, original Porsche key code card, spare key, battery conditioner and car cover."
    ],
