    "description": [
      "The 930 Turbo was Porsche’s first production turbocharged 911 and quickly established itself as a true performance icon. Instantly identifiable thanks to its dramatic wide-body stance, flared rear arches and signature ‘whale tail’ rear spoiler, the 930 combined explosive performance with unmistakable styling.",
      "Today, the 930 Turbo is widely regarded as one of the most collectible and desirable classic 911 variants, continuing to grow in appreciation amongst collectors worldwide. Stunning looks and offers the thrilling analogue driving experience that has made the 930 Turbo such a coveted model amongst collectors and enthusiasts alike.",
      "Powered by its legendary turbocharged flat-six engine, delivering exhilarating performance, the 930 Turbo offers a raw and engaging driving experience synonymous with Porsche’s golden era of engineering. For the 1989 model year, the factory introduced the desirable G50 five-speed gearbox, whilst enhancements also included larger rear torsion bars, upgraded rear anti-roll bars and the fitment of 16-inch Fuchs alloy wheels.",
      "Our ultra-low-mileage UK-supplied example is presented in the exquisite colour combination of Minerva Blue (Colour to Sample) over Pearl White leather (Interior to Sample). The car also benefits from a host of optional extras, including a sunroof, heated driver&#8217;s seat, heated passenger seat, electric height adjustment for both sports seats, piping to the front seats, a luggage compartment trimmed in black velour carpet, rear seat belts, an amplifier system, painted wheel crests and a top-tinted windscreen.",
      "Benefiting from just two owners from new, though effectively a one-owner example, having been retained by the same individual for 36 years.",
      "It is one of the finest examples we have handled and is offered complete with its handbooks including the ever-important Guarantee and Maintenance supplement, original purchase invoice, leather pouch, spare key, tool roll and dedicated history file."
    ],
