    "description": [
      "The McLaren MP4/13 was the first McLaren designed by Adrian Newey and one of the most dominant models in the manufacturer’s history.",
      "This particular example was driven to victory by David Coulthard at the 1998 San Marino Grand Prix, achieving a further five podium finishes, three pole positions and three fastest laps, and contributing significantly to McLaren winning the Constructors’ Championship that year.",
      "One of only two examples in private circulation, the others being retained by McLaren and Mercedes-Benz respectively.",
      "Retained by the factory until 2017, at which time it was one of the cars Sir Ron Dennis chose to purchase upon his departure from the McLaren Group, a testament to the car’s significance."
    ],
