    "description": [
      "Chassis #020 was the 18th of 64 McLaren F1 road cars ever built and it was the only example delivered new in Mid Pearl Blue. It is one of only nine examples that was upgraded by McLaren in period with the instantly recognisable High Downforce Kit.",
      "The car is one of very few single-owner McLaren F1s in existence and featured in the iconic series Top Gear, during which motorsport and Formula 1 legend Murray Walker drove chassis #020 and declared it the “greatest car ever”.",
      "Offered complete with its original handbooks, dedicated fitted luggage, Facom tool chest, original Autoglym cleaning kit and many other factory-delivered F1 accessories, including the highly sought-after TAG Heuer McLaren F1 Owner’s Watch, featuring the chassis number on the dial.",
      "It is accompanied by an incredibly rich history file, with the earliest records predating the production process."
    ],
