    "description": [
      "One of only 150 examples ever produced.",
      "The Aston Martin Valkyrie takes its name from the figure of the Valkyrie in Norse mythology. It is also known by its code names: AM-RB 001 (‘AM’ standing for Aston Martin and ‘RB’ for Red Bull) and ‘Nebula’ (an acronym for Newey, Red Bull and Aston Martin). It is a limited-edition hybrid hypercar developed collaboratively by British automobile manufacturer Aston Martin, Red Bull Racing Advanced Technologies and Cosworth.",
      "Powered by a mid-mounted, 6.5-litre naturally aspirated V12 combined with an electric motor for instant torque, the Valkyrie produces a total output of 1,140 bhp, with 1,000 bhp coming from the V12 alone. Even more impressive is the fact that the car’s structure does not contain a single steel component, allowing it to weigh just 1,355 kg – an attribute more commonly associated with LMP1 or Formula One cars, but delivered here in a road-legal hypercar.",
      "Its exterior is highly aerodynamic, with an extensively open underfloor that harnesses the Venturi effect to generate as much as 1,814 kg (4,000 lb) of downforce at high speed. Openings across the bodywork, including those above the front axle and around the roof intake, work in conjunction with the substantial front splitter to further manage airflow and increase aerodynamic load, while the wheels have been engineered to remain as lightweight as possible without compromising aerodynamic efficiency.",
      "Inside, the conventional instrument cluster is replaced by a collection of carefully positioned displays. Screens in the outer corners provide feeds from the camera-based side mirrors, with another mounted at the top of the centre console, while the race-inspired removable steering wheel incorporates its own display, serving as the driver’s primary instrument panel. Physical dials and switches are positioned alongside it, allowing key adjustments to be made quickly and intuitively while on the move. Carbon-fibre bucket seats complete the purposeful cabin, with the first owner offered a choice of both racing harnesses and conventional seat belts for each seat.",
      "This particular UK supplied example was configured in a unique spec and with a whole host of factory optional extras which include: roof and engine cover in gloss carbon fibre, bespoke exterior paint in Valkyrie Candy Red, black brake calipers, interior hardware exposed twill carbon, steering wheel titanium switches, driver and passenger tub back large squab cushions, debossed Alcantara trim, front and rear Q graphics in Quantum, full Mokume carbon fibre pack, matt black aluminium honeycomb wheels. In addition, the car was specified with clam vanes in satin Mokume carbon fibre, exposed carbon fibre roof strake, suspension shrouds in exposed satin carbon finish, Aston Martin Lagonda wings badge in Titanium, full Inconel system with black exhaust tailpipes, seat pad colour in pure black debossed Alcantara, seat pad and embroidery in Chancellor red, 6-point seat harness in black, steering wheel trim in pure black Alcantara, interior hardware pack in satin Mokume carbon fibre, headlamp scoop in satin Mokume carbon fibre and full paint protective film.",
      "This example has an excellent documented service history from new, with all services carried out back at Aston Martin Gaydon, as detailed below:",
      "2024 February, 140 miles &#8211; Aston Martin Gaydon",
      "2025 March, 213 miles &#8211; Aston Martin Gaydon",
      "2026 April, 288 miles &#8211; Aston Martin Gaydon",
      "The car also benefits from an extended manufacturer’s warranty until November 2027, along with a five-year Collector Service Plan, which expires in February 2030.",
      "Complete with two headphones, spare key, centre wheel lock socket, battery conditioner, handbook, warning triangle, tyre inflation kit, emergency tool kit, towing eye and a dedicated history file that includes a copy of its original invoice and statement of origin."
    ],
