    "description": [
      "One of only four Aston Martin DBR1 Works team cars constructed.",
      "Finished 2nd overall at the 1959 24 Hours of Le Mans.",
      "Played a pivotal role in Aston Martin’s 1959 World Sportscar Championship win.",
      "Originally constructed as the sole DBR3 before conversion to DBR1/4.",
      "A Works car driven by some of the finest drivers of the period, including Stirling Moss, Roy Salvadori, Paul Frère and Maurice Trintignant.",
      "Researched and life history documented by marque expert Stephen Archer and offered complete with a spare engine."
    ],
    "specs": {
      "transmission": "Manual",
      "engine_capacity": "2992cc",
      "fuel": "Petrol"
    }
