    "description": [
      "The Ferrari 812 Competizione marked the ultimate evolution of Ferrari’s front-engined V12 berlinetta, elevating the already formidable 812 Superfast to extraordinary new heights of intensity and precision. Produced in strictly limited numbers, it represented the most focused and extreme expression of Ferrari’s naturally aspirated V12 road car of its era. Drawing upon over seven decades of motorsport heritage, the 812 Competizione fused race-derived engineering with advanced aerodynamics and purposeful design, delivering a truly exceptional blend of performance, theatre and driver engagement.",
      "Powered by a 6.5-litre naturally aspirated V12 engine, screaming to a breathtaking 9,500 rpm, while paired with a 7-speed dual-clutch transmission, it produces a staggering 819 horsepower and 692 Nm of torque. This powerhouse launches from 0–60 mph in just 2.8 seconds, with a top speed exceeding 211 mph.",
      "This particular UK-supplied example was specified from new with a huge list of optional extras, including: special two-layer paint (French Racing Blue), livery in Nero DS and Giallo Fly, airbrushed Scuderia shields, rear diffuser in carbon fibre, front air vents in carbon fibre, carbon fibre underdoor cover, 20&#8243; forged diamond rims, Pirelli coloured tyres, carbon fibre centre wheel cups, black brake callipers, suspension lift, adaptive headlights with SBL function, front and rear parking cameras, Ferrari Tricolore badge, carbon fibre Daytona racing seats, racing seat lifter, carbon fibre inner door handles, carbon fibre dashboard inserts, carbon fibre upper tunnel trim, Alcantara Nero interior, Alcantara dashboard details, Giallo Cavallino stitched on the headrests, stitching in special thread, yellow rev counter, heat-insulating windscreen, Apple CarPlay, high-power Hi-Fi system (JBL), passenger display, full-car PPF and an anti-theft security system with cards.",
      "Although boasting such low mileage, it has an excellent documented service history from new, all carried out by its original supplying dealer:",
      "2024 April, 49 miles &#8211; Graypaul Nottingham Ferrari",
      "2025 March, 56 miles &#8211; Graypaul Nottingham Ferrari",
      "2026 February, 385 miles &#8211; Graypaul Nottingham Ferrari",
      "Presented in indistinguishable from new condition throughout and complete with its original books including the service/warranty supplement, car cover, battery conditioner and a dedicated history file.",
      "The car also benefits from the remainder of its 4 year warranty until May 2027, along with its 7 year service plan, which expires in May 2030."
    ],
