    "description": [
      "The Porsche 991 GT2 RS represents the absolute pinnacle of the 991 generation and is widely regarded as one of the greatest modern era 911s ever produced. Developed with direct influence from Porsche Motorsport, the GT2 RS combines brutal turbocharged performance with genuine Rennsport pedigree, delivering an intensity and level of driver engagement few modern supercars can rival.",
      "Powered by a 3.8-litre twin turbocharged flat-six producing 700 horsepower, the GT2 RS is capable of reaching 0–60mph in just 2.7 seconds and a top speed of 211mph. With rear wheel drive, extensive lightweight construction and Porsche’s lightning fast 7-speed PDK transmission, it offers a driving experience that is both visceral and immensely capable, combining savage performance with extraordinary chassis precision. Upon its release, the GT2 RS set new benchmarks for road legal performance cars and famously recorded a Nürburgring lap time of 6 minutes 47.3 seconds, making it the fastest production car around the circuit at the time and further cementing its position amongst the all time great Porsche models.",
      "This UK supplied example was commissioned with the following factory options and features, which include but are not limited to: Weissach package, Clubsport package, carbon bucket sport seats, carbon fibre interior trim, centre console trim in carbon fibre, sports steering wheel in alcantara, PDK gear sector in alcantara, roof lining in alcantara, rev counter dial face in black, cruise control, Bose surround sound, light design package, automatically dimming mirrors with integrated rain sensors, Porsche communication management system including online navigation, voice control, door sill guards in carbon fibre, magnesium wheels painted in satin black, LED main headlights in black including Porsche Dynamic Light System Plus (PDLS Plus), Porsche ceramic composite brakes (PCCB), Porsche active suspension management (PASM), sports design exterior mirrors in carbon fibre, tinted taillights, reversing camera, rear-axle steering, headlight washer system, windscreen top tint, fuel filler cap with an aluminium look finish and Porsche vehicle tracking systems plus (PVTS Plus).",
      "As well as showing exceptionally low mileage from new, it has been maintained with all servicing carried out by official Porsche Centres:",
      "2021 March, 1,521 miles &#8211; Porsche Centre Reading",
      "2023 July, 1,634 miles &#8211; Porsche Centre Portsmouth",
      "2025 August, 3,058 miles &#8211; Porsche Centre Portsmouth",
      "Presented in &#8216;as new&#8217; condition throughout and offered complete with its original handbooks including the all important guarantee/maintenance supplement, spare key, car cover, battery conditioner, warning triangle, first aid kit, tyre inflator kit, tools and a dedicated history file."
    ],
