    "description": [
      "The Ferrari 599 GTO represents one of the most exhilarating and exclusive road-going Ferraris ever produced, with just 599 examples built worldwide. As the fastest road car Ferrari had ever built at the time of its release, it is powered by a 6.0-litre naturally aspirated V12 derived directly from the Ferrari Enzo, producing 661bhp and delivering a truly visceral driving experience. Lightweight, uncompromising and engineered with a clear focus on performance, the 599 GTO stands as a modern classic and a landmark in Ferrari’s front engined V12 lineage.",
      "Powered by its V12 engine, the 599 GTO was able to lap Ferrari’s Fiorano test circuit in just 1 minute 24 seconds, one second faster than the Ferrari Enzo. Reaching 0–62 mph time of just 3.3 seconds and a top speed in excess of 208 mph, it is safe to say the 599 GTO more than delivered. Named after its 5,999cc engine displacement, the 599 GTO had big shoes to fill, being only the third GTO-designated model, following the legendary 250 GTO and 288 GTO.",
      "A UK-supplied Atelier example specified in the rare exterior colour of Rosso Formula 1 2007, Ferrari&#8217;s special three-layer paint finish. An expensive option when new, but certainly worth every penny, as it is one of the most attractive 599 GTOs we have ever handled or seen. Factory optional extras include: Atelier programme specification, two-tone paintwork, Nero DS livery, carbon fibre Daytona-style racing seats, prancing horse and &#8216;GTO&#8217; logos stitched to the headrests, nero leather interior, Extracampionario interior colour, red Alcantara and nero seat centre sections, Speciale Rosso contrast stitching, Giallo instrument cluster, elegant interior upholstery, matte carbon fibre dashboard inserts, road-legal roll bar, Rosso Scuderia brake callipers, carbon fibre luggage compartment trim, carbon fibre wheel centre caps, gloss black wheels, carbon fibre headlight buckets, matte carbon fibre exterior sill plates, privacy rear windows, rear parking sensors, Ferrari iPod connection and satellite navigation.",
      "The car benefits from a documented service history from new, with services carried out as follows:",
      "2012 October, 3,105 miles &#8211; Maranello Egham, Ferrari",
      "2014 May, 3,379 miles &#8211; Maranello Egham, Ferrari",
      "2019 September, 6,164 miles &#8211; Maranello Egham, Ferrari",
      "2023 February, 6,468 miles &#8211; Maranello Egham, Ferrari",
      "2024 May, 6,502 miles &#8211; DK Engineering",
      "2025 October, 7,282 miles &#8211; Graypaul Nottingham, Ferrari",
      "Presented in exceptional condition throughout and offered with its Ferrari handbooks including the ever-important service/warranty supplement, pouch, spare key with special 599 GTO keyring, Ferrari torch, dedicated history file that contains its original Sales Invoice and in addition, a model-specific registration number."
    ],
